import { installConnector } from '@projexlight/connector-snowflake';
const { install_id } = await installConnector({
  tenant_id, account_url: 'acme.snowflakecomputing.com',
  warehouse: 'PROJEX_WH', database: 'PROJEX_DB', role: 'PROJEX_RW',
  credentials: { username: 'PROJEX_SVC', private_key_pem: '...' }, // vault-stored
});

import { registerBinding } from '@projexlight/connector-snowflake';
await registerBinding({
  install_id, source_table: 'billing.invoice',
  target_table: 'ANALYTICS.FACT_INVOICE',
  sync_mode: 'push', schedule: 'hourly',
});

import { queryFederated } from '@projexlight/connector-snowflake';
const { rows, warehouse_seconds } = await queryFederated({
  install_id, query: 'SELECT plan_tier, SUM(mrr_cents) FROM ANALYTICS.FACT_INVOICE GROUP BY 1',
});

// driven by event subscription:
subscribeEvents('tenant.offboarded.v1', async (e) => {
  await shredCredentialsForTenant(e.payload.tenant_id);
});
